pub(crate) fn types_plain_enums(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut plain: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Enum { name, variants, .. } => {
                let name = *name;
                let mut holds = false;
                for variant in variants.iter() {
                    match &variant.fields {
                        VariantFields::Unit => { },
                        _ => { holds = true; },
                    }
                }
                if !holds { plain.insert(names.resolve(name).to_owned()); }
            },
            _ => { },
        }
    }
    plain
}

pub(crate) fn widths_written(names: &winnow_grammar::InternerContext, ty: &Type, at_c: bool, span: &Span, out: &mut Vec<Finding>) {
    let name = names.resolve(ty.name).to_owned();
    if at_c && name == "int" {
        out.push(refusal("NK1262", span.clone(), String::from("`int` can't be written where C sees the value."), vec![String::from("An `int` holds the values of an `i64`, but how it is stored is the compiler's choice (ADR-285 D37); C reads the bytes, so the width has to be written.")], String::from("Write `i64` here, or the fixed width the C side declares.")));
        return;
    }
    if !at_c && nikaia_std::list::contains(&UNOFFERED_WIDTHS, &name) {
        out.push(refusal("NK1135", span.clone(), format!("There's no type called `{}`.", name), vec![String::from("Nikaia's integers are `int` and the fixed widths `i64`, `i32`, `u8`, `u32` and `u64` (Part I 2.2); Rust's other widths are written only in an `extern \"C\"` declaration.")], String::from("Write `int` for an ordinary number, or the fixed width that holds the values.")));
        return;
    }
    let lanes = name == "simd::Fixed" || name == "simd::Lanes" || name == "simd::Mask";
    let mut first = true;
    for argument in ty.generics.iter() {
        if !(lanes && first) { widths_written(names, argument, at_c, span, out); }
        first = false;
    }
    widths_written_maybe(names, (*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), at_c, span, out);
}

pub(crate) fn widths_written_maybe(names: &winnow_grammar::InternerContext, ty: Option<&Type>, at_c: bool, span: &Span, out: &mut Vec<Finding>) { widths_written(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, at_c, span, out); }

pub(crate) fn maybe_written(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_at(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

pub(crate) fn maybe_written_foreign(names: &winnow_grammar::InternerContext, ty: Option<&Type>, known: &collections::BTreeSet<String>, span: &Span, out: &mut Vec<Finding>) { written_foreign(names, match ty { Some(__nikaia_value) => __nikaia_value, None => return }, known, false, span, out); }

pub(crate) fn block_types(names: &winnow_grammar::InternerContext, block: &Block, known: &collections::BTreeSet<String>, views: &collections::BTreeSet<String>, plain: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, value, .. } => {
                maybe_written(names, (ty).as_ref(), known, &stmt.span, out);
                types_text_by_ref_maybe(names, (ty).as_ref(), "`let`", views, &format!("let {}", stmt.span.start), &stmt.span, out);
                widths_written_maybe(names, (ty).as_ref(), false, &stmt.span, out);
                if ty.is_some() {
                    let annotated: &Type = match ty { Some(__nikaia_value) => __nikaia_value, None => continue };
                    for inner in annotated.generics.iter() { types_word_by_ref(names, inner, plain, "type argument", &stmt.span, out); }
                }
                blocks_types(names, value, known, views, plain, out);
            },
            Stmt::Comptime { value, .. } => { blocks_types(names, value, known, views, plain, out); },
            Stmt::Expr(value) => { blocks_types(names, value, known, views, plain, out); },
            Stmt::Return(value) => { blocks_types(names, match value { Some(__nikaia_value) => __nikaia_value, None => continue }, known, views, plain, out); },
            Stmt::Assign { target, value, .. } => {
                blocks_types(names, target, known, views, plain, out);
                blocks_types(names, value, known, views, plain, out);
            },
            Stmt::For { body, .. } => { block_types(names, body, known, views, plain, out); },
            Stmt::While { body, .. } => { block_types(names, body, known, views, plain, out); },
            _ => { },
        }
    }
}

pub(crate) fn blocks_types(names: &winnow_grammar::InternerContext, expr: &Expr, known: &collections::BTreeSet<String>, views: &collections::BTreeSet<String>, plain: &collections::BTreeSet<String>, out: &mut Vec<Finding>) {
    match expr {
        Expr::Block(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Unsafe(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Overlap(block, _) => { block_types(names, block, known, views, plain, out); },
        Expr::Closure { body, .. } => { block_types(names, body, known, views, plain, out); },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            blocks_types(names, func, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            blocks_types(names, receiver, known, views, plain, out);
            for arg in args.iter() { blocks_types(names, arg, known, views, plain, out); }
            for setting in config.iter() { blocks_types(names, &setting.value, known, views, plain, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            block_types(names, then_branch, known, views, plain, out);
            block_types(names, match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, known, views, plain, out);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            blocks_types(names, expr, known, views, plain, out);
            block_types(names, handler, known, views, plain, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { blocks_types(names, &arm.body, known, views, plain, out); } },
        Expr::Select(arms, _) => { for arm in arms.iter() { block_types(names, &arm.body, known, views, plain, out); } },
        _ => { },
    }
}

pub(crate) fn written_foreign(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_slice && !ty.generics.is_empty() {
        written_at(names, nikaia_std::index::get(&ty.generics, 0), known, false, span, out);
        return;
    }
    written_at_the_boundary(names, ty, known, a_parameter, true, span, out);
}

pub(crate) fn written_at(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, span: &Span, out: &mut Vec<Finding>) { written_at_the_boundary(names, ty, known, a_parameter, false, span, out); }

pub(crate) fn written_at_the_boundary(names: &winnow_grammar::InternerContext, ty: &Type, known: &collections::BTreeSet<String>, a_parameter: bool, at_c: bool, span: &Span, out: &mut Vec<Finding>) {
    if ty.is_mut && !at_c {
        out.push(refusal("NK1158", span.clone(), String::from("`ref mut` can only be used when talking to C."), vec![String::from("`ref mut` is only for `extern \"C\"` declarations. Everywhere else, Nikaia has its own way to say it.")], String::from("Put `mut` in front of the name instead: `fn fill(mut out: Vec[i64])`.")));
        return;
    }
    let name = names.resolve(ty.name).to_owned();
    if name == "char" {
        out.push(refusal("NK1135", span.clone(), String::from("There's no type called `char`."), vec![String::from("One Unicode character is a `scalar`, and one byte of text is a `u8`: which of the two a character is depends on how the text is read (Part I 2.6).")], String::from("Write `scalar` for a character, or `u8` for a byte.")));
        return;
    }
    simd_written(names, &name, ty, span, out);
    if !a_parameter && !ty.is_view && !ty.is_slice && ty.count.is_none() && ty.generics.len() == 1 && name == "Array" {
        let element = names.resolve(nikaia_std::index::get(&ty.generics, 0).name).to_owned();
        out.push(refusal("NK1182", span.clone(), format!("`Array[{}]` needs a length here.", element), vec![format!("`Array[{}]` without a length only works for a parameter, where each call supplies the length. A field or a result has no call to take it from.", element)], format!("Use `Vec[{}]` for a list that can grow, `ref Array[{}]` to look at elements something else keeps, or `Array[{}, N]` to write the length down.", element, element, element)));
        return;
    }
    if ty.count.is_some() { return; }
    if ty.is_slice {
        for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
        return;
    }
    if !ty.is_tuple && (*ty.code).is_none() && !known.contains(&name) && !name.contains("::") { out.push(nothing_declares(&name, known, span)); }
    for argument in ty.generics.iter() { written_at(names, argument, known, false, span, out); }
    maybe_written(names, (*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), known, span, out);
}

pub(crate) fn nothing_declares(name: &str, known: &collections::BTreeSet<String>, span: &Span) -> Finding {
    let module = std_module_of(name, known);
    if !module.is_empty() { return refusal("NK1135", span.clone(), format!("`{}` needs its module in front of it.", name), vec![format!("Its full name is `{}::{}`: a type from a module is written with the module's name.", module, name)], format!("Write `use std::{}` at the top of the file, and `{}::{}` here.", module, module, name)); }
    refusal("NK1135", span.clone(), format!("There's no type called `{}`.", name), vec![String::from("A type is either built in, declared in your program with `struct` or `enum`, provided by `std`, or a type parameter.")], format!("Check the spelling, or declare `{}` with `struct` or `enum`.", name))
}

pub fn nobody_knows(name: &str, own: &Ledger, library: &Ledger) -> bool {
    if nikaia_std::list::contains(&BUILT_IN, &name) || own.types.contains_key(name) || library.types.contains_key(name) { return false; }
    let c: Vec<scalar> = nikaia_std::list::chars(name.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if ((at + 1) as usize) < c.len() && *nikaia_std::index::get(&c, (at) as usize) == ':' && *nikaia_std::index::get(&c, (at + 1) as usize) == ':' { last = at; } }
    let wanted = if last < 0 { format!("::{}", name) } else { format!("{}::", slice(&c, 0, last)) };
    for ledger in [own, library] {
        for (key, _) in ledger.types.iter() { if last < 0 && key.ends_with(&wanted) || last >= 0 && key.starts_with(&wanted) { return false; } }
        for (key, _) in ledger.functions.iter() { if last >= 0 && key.starts_with(&wanted) { return false; } }
    }
    true
}

pub(crate) fn std_module_of(name: &str, known: &collections::BTreeSet<String>) -> String {
    let ending = format!("::{}", name);
    for key in known.iter() {
        if key.ends_with(&ending) {
            let c: Vec<scalar> = nikaia_std::list::chars(key.chars());
            let at = find_text(&c, 0, "::");
            let module = slice(&c, 0, at);
            for one in STD_MODULES.iter() {
                let one = *one;
                if module == one { return module; }
            }
            return String::from("");
        }
    }
    String::from("")
}

